// Idempotency via Redis SETNX TTL 24h (lesson 22 super-prompt).
const webhookId = $input.item.json.headers?.['x-webhook-id']
  || $input.item.json.body?.id
  || $input.item.json.body?.messageId
  || crypto.randomUUID();

const dedupKey = `webhook:chatbot-llm:${webhookId}`;

// SETNX retorna 'OK' se inserido, null se ja existe
const result = await this.helpers.redis.set(dedupKey, '1', 'EX', 86400, 'NX');

if (!result) {
  throw new Error('DUPLICATE_WEBHOOK');
}

return [{ json: { ...$input.item.json, _dedup_key: dedupKey } }];

// PII scrubber (espelho de backend/app/services/pii.py)
// Bloqueia fluxo se PII detectado -> handoff humano LGPD art. 7 I.
const items = $input.all();
const out = [];
const patterns = [
  { label: 'email',    re: /\b[\w.+-]+@[\w-]+\.[\w.-]+\b/g },
  { label: 'data',     re: /\b\d{2}[\/\-\.]\d{2}[\/\-\.]\d{4}\b|\b\d{4}-\d{2}-\d{2}\b/g },
  { label: 'placa_veiculo',    re: /\b[A-Z]{3}-?\d[A-Z]\d{2}\b|\b[A-Z]{3}-?\d{4}\b/g },
  { label: 'cnpj',     re: /\b\d{2}\.?\d{3}\.\d{3}\/\d{4}-?\d{2}\b/g },
  { label: 'cpf',      re: /\b\d{3}\.\d{3}\.\d{3}-?\d{2}\b/g },
  { label: 'pis',      re: /\b\d{3}\.\d{5}\.\d{3}\b/g },
  { label: 'rg',       re: /\b\d{1,2}\.\d{3}\.?\d{3}-?[\dxX]\b/g },
  { label: 'titulo',   re: /\b\d{4}\s?\d{4}\s?\d{4}\b/g },
  { label: 'phone_br', re: /(?:\+?55\s?)?\(?\d{2}\)?\s?9?\d{4}[\s-]?\d{4}/g },
  { label: 'cep',      re: /\b\d{5}-?\d{3}\b/g },
  { label: 'cartao',   re: /\b\d{4}[\s-]?\d{4}[\s-]?\d{4}[\s-]?\d{4}\b|\b\d{4}[\s-]?\d{6}[\s-]?\d{5}\b/g }
];
for (const item of items) {
  const raw = (item.json.raw_text || '').toString();
  let scrubbed = raw;
  const findings = {};
  let cnt = 0;
  for (const p of patterns) {
    const m = scrubbed.match(p.re);
    if (m && m.length) {
      findings[p.label] = m.length;
      cnt += m.length;
      scrubbed = scrubbed.replace(p.re, '[' + p.label.toUpperCase() + '_REDACTED]');
    }
  }
  const blocked = cnt > 0;
  out.push({
    json: {
      sender: item.json.sender || 'unknown',
      instance: item.json.instance || 'cartorio-2notas-uberlandia',
      canal: item.json.canal || 'whatsapp',
      scrubbed: scrubbed,
      findings: findings,
      redaction_count: cnt,
      blocked: blocked,
      consent_granted: !blocked,
      timestamp: new Date().toISOString()
    }
  });
}
return out;

// Decide response: PII nao bloqueia mais o atendimento (dados ja mascarados).
// Handoff so para decisao juridica/urgencia/isencao (sinalizado pelo LLM via [[ACTION:humano]]).
const items = $input.all();
const out = [];
for (const item of items) {
  const scrub = $('PII Scrubber').item.json;
  const mcp = item.json || {};
  const isPii = scrub && scrub.redaction_count > 0;
  const toolResult = mcp.result || mcp;
  let responseText = toolResult.response || (toolResult.content && toolResult.content[0] && toolResult.content[0].text) || null;
  let ok = toolResult.status === 'ok' && responseText;
  let needsHuman = false;

  if (ok && responseText) {
    // Sinalizador de escalonamento humano vindo do LLM (HITL juridico)
    needsHuman = /\[\[ACTION:humano\]\]/i.test(responseText);
    // Remove o sinalizador interno da resposta final
    responseText = responseText.replace(/\s*\[\[ACTION:[^\]]+\]\]\s*/gi, '\n').trim();
  }

  let r;
  if (ok) {
    r = {
      status: needsHuman ? 'ok_with_human_followup' : 'ok',
      response: responseText,
      sender: scrub.sender || 'unknown',
      pii_blocked: isPii,
      pii_redaction_count: scrub.redaction_count || 0,
      needs_human_handoff: needsHuman,
      model: toolResult.model || 'deepseek-v4-flash',
      tokens_in: toolResult.tokens_in || null,
      tokens_out: toolResult.tokens_out || null,
      latency_ms: toolResult.latency_ms || null,
      provider: toolResult.provider || 'opencode_go',
      transport: 'mcp'
    };
  } else {
    // LLM erro: primeiro fallback educado, nao handoff automatico
    r = {
      status: 'llm_error',
      response: 'Desculpe, tive uma instabilidade momentanea. Pode repetir sua pergunta? Se preferir, digite /humano para falar com o escrevente.',
      sender: scrub.sender || 'unknown',
      pii_blocked: isPii,
      pii_redaction_count: scrub.redaction_count || 0,
      needs_human_handoff: false,
      model: toolResult.model || null,
      tokens_in: toolResult.tokens_in || null,
      tokens_out: toolResult.tokens_out || null,
      latency_ms: toolResult.latency_ms || null,
      provider: toolResult.provider || 'opencode_go',
      transport: 'mcp'
    };
  }
  out.push({ json: r });
}
return out;
